from .base_cl_tool import BaseClToolInterface


class TiltToolsInterface(BaseClToolInterface):
    """Keywords for tilt tools related commands."""

    def calibrate_tilt(self, tilt_id=None, tilt_dn=None, timeout='1min', **kwargs):
        """
        Calibrates tilts in one or multiple sites.

        :param string tilt_id: Tilt ids. Calibrates all tilts if id and distname not given.
        :param string tilt_dn: Tilt distnames. Calibrates all tilts if id and distname not given.
        :return: Path(s) of collected file(s).
        :rtype: list

        :warning: If both tilt_id and tilt_dn are provided, tilt_id will be used and tilt_dn will will be ignored.
        """

        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        timeout = self._convert_to_secs(timeout)
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        params = {'ne': ne, 'pw': pw, 'timeout': timeout, 'id': tilt_id, 'distname': tilt_dn}
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = ['nolog'] if nolog else []
        return self._execute_cl_tool_operation(alias=alias, timeout=timeout, operation='calibratetilt', params=params, trs_ip=ne, flags=flags)

