        """
        Configures tilts in one or multiple sites.

        :param string config_file: Path to Tilt configuration file.
        :param string tilt_id: Tilt ids. Configures all tilts if id and distname not given.
        :param string tilt_dn: Tilt distnames. Configures all tilts if id and distname not given.
        :return: Path(s) of collected file(s).
        :rtype: list

        :warning: If both tilt_id and tilt_dn are provided, tilt_id will be used and tilt_dn will will be ignored.
        """

        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        timeout = self._convert_to_secs(timeout)
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        params = {'ne': ne, 'pw': pw, 'timeout': timeout, 'configurationfile': config_file, 'id': tilt_id, 'distname': tilt_dn}
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = ['nolog'] if nolog else []
        return self._execute_cl_tool_operation(alias=alias, timeout=timeout, operation='configuretilt', params=params, trs_ip=ne, flags=flags)

